// Builds a TriageOps ticket from each Gmail message and signs it.
// Signature = "sha256=" + hex HMAC-SHA256 of "{timestamp}.{rawBody}" with TRIAGEOPS_WEBHOOK_SECRET.
// The HTTP Request node sends rawBody byte for byte, so the server computes the same HMAC.
// n8n settings needed: NODE_FUNCTION_ALLOW_BUILTIN=crypto and N8N_BLOCK_ENV_ACCESS_IN_NODE=false.
const crypto = require('crypto');

const secret = $env.TRIAGEOPS_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('TRIAGEOPS_WEBHOOK_SECRET is not set in the n8n environment');
}

// Map sender domains to MSP client names. Unknown domains fall back to the domain itself.
const CUSTOMERS = {
  'harbourdental.co.uk': 'Harbour Dental Group',
  'northgateaccountancy.co.uk': 'Northgate Accountancy',
};

return $input.all().map((item) => {
  const mail = item.json;
  const sender = (mail.from && mail.from.value && mail.from.value[0]) || {};
  const address = String(sender.address || 'unknown@unknown.invalid').toLowerCase();
  const domain = address.split('@')[1] || 'unknown';

  let subject = String(mail.subject || '').replace(/\s+/g, ' ').trim();
  if (subject.length < 3) subject = `Email from ${address}`;
  subject = subject.slice(0, 200);

  let body = String(mail.text || mail.snippet || '').trim();
  if (body.length < 10) body = `${subject}\n\n${body}`.trim();
  if (body.length < 10) body = `${body} (no message body)`;
  body = body.slice(0, 4000);

  const payload = {
    channel: 'email',
    customer: CUSTOMERS[domain] || domain,
    requester: address,
    subject,
    body,
    // Lets TriageOps return the original ticket if n8n retries the same email.
    external_id: mail.id ? `gmail:${mail.id}` : undefined,
  };

  const rawBody = JSON.stringify(payload);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = 'sha256=' + crypto
    .createHmac('sha256', secret)
    .update(`${timestamp}.${rawBody}`, 'utf8')
    .digest('hex');

  return { json: { rawBody, timestamp, signature, gmailMessageId: mail.id } };
});

